79	/// Low level assembler implementation for Aarch64.
80	pub(crate) struct Assembler {
81	    /// The machine instruction buffer.
82	    buffer: MachBuffer<Inst>,
83	    /// Constant emission information.
84	    emit_info: EmitInfo,
85	    /// Emission state.
86	    emit_state: EmitState,
87	}
88	
89	impl Assembler {
90	    /// Create a new Aarch64 assembler.
91	    pub fn new(shared_flags: settings::Flags) -> Self {
92	        Self {
93	            buffer: MachBuffer::<Inst>::new(),
94	            emit_state: Default::default(),
95	            emit_info: EmitInfo::new(shared_flags),
96	        }
97	    }
98	}
99	
100	impl Assembler {
101	    /// Return the emitted code.
102	    pub fn finalize(mut self, loc: Option<SourceLoc>) -> MachBufferFinalized<Final> {
103	        let constants = Default::default();
104	        let stencil = self
105	            .buffer
106	            .finish(&constants, self.emit_state.ctrl_plane_mut());
107	        stencil.apply_base_srcloc(loc.unwrap_or_default())
108	    }
109	
110	    fn emit(&mut self, inst: Inst) {
111	        self.emit_with_island(inst, Inst::worst_case_size());
112	    }
113	
114	    fn emit_with_island(&mut self, inst: Inst, needed_space: u32) {
115	        if self.buffer.island_needed(needed_space) {
116	            let label = self.buffer.get_label();
117	            let jmp = Inst::Jump {
118	                dest: BranchTarget::Label(label),
119	            };
120	            jmp.emit(&mut self.buffer, &self.emit_info, &mut self.emit_state);
121	            self.buffer
122	                .emit_island(needed_space, self.emit_state.ctrl_plane_mut());
123	            self.buffer
124	                .bind_label(label, self.emit_state.ctrl_plane_mut());
125	        }
126	        inst.emit(&mut self.buffer, &self.emit_info, &mut self.emit_state);
127	    }
128	
129	    /// Load a constant into a register.
130	    pub fn load_constant(&mut self, imm: u64, rd: WritableReg) {
131	        let writable = rd.map(Into::into);
132	        Inst::load_constant(writable, imm, &mut |_| writable)
133	            .into_iter()
134	            .for_each(|i| self.emit(i));
135	    }
136	
137	    /// Store a pair of registers.
138	    pub fn stp(&mut self, xt1: Reg, xt2: Reg, addr: Address) {
139	        let mem: PairAMode = addr.try_into().unwrap();
140	        self.emit(Inst::StoreP64 {
141	            rt: xt1.into(),
142	            rt2: xt2.into(),
143	            mem,
144	            flags: MemFlags::trusted(),
145	        });
146	    }
147	
148	    /// Store a register.
149	    pub fn str(&mut self, reg: Reg, addr: Address, size: OperandSize) {
150	        let mem: AMode = addr.try_into().unwrap();
151	        let flags = MemFlags::trusted();
152	
153	        use OperandSize::*;
154	        let inst = match (reg.is_int(), size) {
155	            (_, S8) => Inst::Store8 {
156	                rd: reg.into(),
157	                mem,
158	                flags,
159	            },
160	            (_, S16) => Inst::Store16 {
161	                rd: reg.into(),
162	                mem,
163	                flags,
164	            },
165	            (true, S32) => Inst::Store32 {
166	                rd: reg.into(),
167	                mem,
168	                flags,
169	            },
170	            (false, S32) => Inst::FpuStore32 {
171	                rd: reg.into(),
172	                mem,
173	                flags,
174	            },
175	            (true, S64) => Inst::Store64 {
176	                rd: reg.into(),
177	                mem,
178	                flags,
179	            },
180	            (false, S64) => Inst::FpuStore64 {
181	                rd: reg.into(),
182	                mem,
183	                flags,
184	            },
185	            (_, S128) => Inst::FpuStore128 {
186	                rd: reg.into(),
187	                mem,
188	                flags,
189	            },
190	        };
191	
192	        self.emit(inst);
193	    }
