56	    fn frame_setup(&mut self) {
57	        let lr = regs::lr();
58	        let fp = regs::fp();
59	        let sp = regs::sp();
60	        let addr = Address::pre_indexed_from_sp(-16);
61	
62	        self.asm.stp(fp, lr, addr);
63	        self.asm.mov_rr(sp, writable!(fp), OperandSize::S64);
64	        self.move_sp_to_shadow_sp();
65	    }
66	
67	    fn check_stack(&mut self, _vmctx: Reg) {
68	        // TODO: Implement when we have more complete assembler support.
69	    }
70	
71	    fn frame_restore(&mut self) {
72	        assert_eq!(self.sp_offset, 0);
73	
74	        let lr = regs::lr();
75	        let fp = regs::fp();
76	        let addr = Address::post_indexed_from_sp(16);
77	
78	        self.asm.ldp(fp, lr, addr);
79	        self.asm.ret();
80	    }
81	
82	    fn reserve_stack(&mut self, bytes: u32) {
83	        if bytes == 0 {
84	            return;
85	        }
86	
87	        let sp = regs::sp();
88	        self.asm
89	            .sub_ir(bytes as u64, sp, writable!(sp), OperandSize::S64);
90	        self.move_sp_to_shadow_sp();
91	
92	        self.increment_sp(bytes);
93	    }
94	
95	    fn free_stack(&mut self, bytes: u32) {
96	        if bytes == 0 {
97	            return;
98	        }
99	
100	        let sp = regs::sp();
101	        self.asm
102	            .add_ir(bytes as u64, sp, writable!(sp), OperandSize::S64);
103	        self.move_sp_to_shadow_sp();
104	
105	        self.decrement_sp(bytes);
106	    }
107	
108	    fn reset_stack_pointer(&mut self, offset: SPOffset) {
109	        self.sp_offset = offset.as_u32();
110	    }
111	
112	    fn local_address(&mut self, local: &LocalSlot) -> Address {
113	        let (reg, offset) = local
114	            .addressed_from_sp()
115	            .then(|| {
116	                let offset = self.sp_offset.checked_sub(local.offset).expect(&format!(
117	                    "Invalid local offset = {}; sp offset = {}",
118	                    local.offset, self.sp_offset
119	                ));
120	                (regs::shadow_sp(), offset)
121	            })
122	            .unwrap_or((regs::fp(), local.offset));
123	
124	        Address::offset(reg, offset as i64)
125	    }
