143	    fn store(&mut self, src: RegImm, dst: Address, size: OperandSize) {
144	        let src = match src {
145	            RegImm::Imm(v) => {
146	                let imm = match v {
147	                    I::I32(v) | I::F32(v) => v as u64,
148	                    I::F64(v) | I::I64(v) => v,
149	                    I::V128(_) => unreachable!(),
150	                };
151	                let scratch = regs::scratch();
152	                self.asm.load_constant(imm, writable!(scratch));
153	                if v.is_float() {
154	                    let float_scratch = regs::float_scratch();
155	                    self.asm
156	                        .mov_to_fpu(scratch, writable!(float_scratch), v.size());
157	                    float_scratch
158	                } else {
159	                    scratch
160	                }
161	            }
162	            RegImm::Reg(reg) => reg,
163	        };
164	
165	        self.asm.str(src, dst, size);
166	    }
