172	    fn call(
173	        &mut self,
174	        stack_args_size: u32,
175	        mut load_callee: impl FnMut(&mut Self) -> (CalleeKind, CallingConvention),
176	    ) -> u32 {
177	        let alignment: u32 = <Self::ABI as abi::ABI>::call_stack_align().into();
178	        let addend: u32 = <Self::ABI as abi::ABI>::arg_base_offset().into();
179	        let delta = calculate_frame_adjustment(self.sp_offset().as_u32(), addend, alignment);
180	        let aligned_args_size = align_to(stack_args_size, alignment);
181	        let total_stack = delta + aligned_args_size;
182	        self.reserve_stack(total_stack);
183	        let (callee, call_conv) = load_callee(self);
184	        match callee {
185	            CalleeKind::Indirect(reg) => self.asm.call_with_reg(reg, call_conv),
186	            CalleeKind::Direct(idx) => self.asm.call_with_name(idx, call_conv),
187	            CalleeKind::LibCall(lib) => self.asm.call_with_lib(lib, scratch(), call_conv),
188	        }
189	
190	        total_stack
191	    }
